import{_ as a}from"./chunks/bb86b2976d876d31587d.BfM7xQ_P.js";import{_ as t,C as l,o as i,c as o,j as e,a as s,E as n,a6 as c}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"创业是现代的生存方式（如何逃离薪酬奴役）","description":"","frontmatter":{"title":"创业是现代的生存方式（如何逃离薪酬奴役）","originalTitle":"Entrepreneurship Is Modern Survival (How To Escape Wage Slavery)","date":"2023-07-21","originalUrl":"https://thedankoe.com/letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery/","minutes":14,"sourceHash":"3bec659ef3d99b86b920eeb5b943b5cc3068c5b79279e8ccd14902b11a1c7bee","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery/"}]]},"headers":[],"relativePath":"letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery.md","filePath":"letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery.md"}'),m={name:"letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery.md"};function h(u,p,d,g,b,f){const r=l("ArticleMeta");return i(),o("div",null,[p[0]||(p[0]=e("h1",{id:"创业是现代的生存方式-如何逃离薪酬奴役",tabindex:"-1"},[s("创业是现代的生存方式（如何逃离薪酬奴役） "),e("a",{class:"header-anchor",href:"#创业是现代的生存方式-如何逃离薪酬奴役","aria-label":'Permalink to "创业是现代的生存方式（如何逃离薪酬奴役）"'},"​")],-1)),n(r),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/qHNzBdTr_54?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>这封信可能会让一些人急眼。</p><p>所以，我请求你保持开放的心态。</p><p>如果没有开放的心态，你就不可能从别人的视角中接收到哪怕一丝一毫能<em>帮助</em>你生活的真理（无论它有多微小）。</p><p>记住，这是我的初衷。</p><p>为了帮助，而不是伤害。</p><p>如果你曲解了我说的话，不管多难听，最终伤害你的都是你自己。</p><p>即使我的本意就是伤害你，有些人也可能会将其视为一种积极因素。如果你选择受伤害，你就会受到伤害。</p><p>如果你感觉自己的大脑开始封闭，请克制住反击的冲动。你了解这种感觉。在这种时候，除了外部世界灌输给你的那些负面垃圾之外，你很难产生任何其他的想法。</p><p>带着这个前提，让我们直接切入正题。</p><p><em>你是个奴隶。</em></p><p>我也是个奴隶。</p><p>如果所有人都是奴隶，奴隶就不会知道自己是奴隶。</p><p>仅仅因为那种人人都知道且痛恨的“奴隶制”已经不复存在，并不意味着奴役就不存在了。</p><p>不，我说的不是性奴役，尽管许多色情片沉迷者可能属于这一类。</p><p>我说的是精神和财务上的奴役。</p><blockquote><p>奴隶（名词）—— 被迫为他人工作、服从他人并被视为他人财产的人。</p></blockquote><p>这个定义中的关键词是“被迫（force）”。</p><p>“Force（力量/强迫）”可以有多种定义和语境。</p><p>为了保持连贯，我们将使用这个定义：</p><blockquote><p>力量（名词）—— 作为物理行动或运动属性的强度或能量。</p></blockquote><p>换句话说，有某种东西在推动你做一件事而不是另一件事。那个“东西”越强大，你被奴役的程度就越深。</p><p>在过去，奴隶在某些情况下可以逃跑，但他们会耗尽食物、水和住所，直至死亡。</p><p>既然如此，奴役是受生存影响的。</p><p>正如我们之前讨论过的，人类的生存并非纯物理层面的，它是概念层面的。</p><p>人类为了维持形态、自我、自负或身份认同而生存。随便你怎么去给意识中的这种区分贴标签。</p><p>一些常见的例子：</p><p><strong>政治意识形态</strong></p><p>如果你认同自己是共和党人或民主党人，而你的信仰受到了挑战，你会感受到一种<em>生理压力反应</em>，促使你去捍卫这些信仰。</p><p>你的生存感到了威胁，因为你把一个观念当成了你自身的一部分，而“你自身”同样也是一个观念。</p><p><strong>运动队</strong></p><p>你有没有注意到，当人们争论哪支运动队会赢时，他们会明显变得愤怒？尤其是当他们还下了注的时候。</p><p>你的“团队精神”让你感觉自己似乎是某个比自己更宏大事物的一部分。这就是你的精神寄托。但这没必要让你的心理健康变得更糟。</p><p><strong>你的身份认同</strong></p><p>你是个咖啡挑剔狂吗？健康专家？高效人士？</p><p>如果有人叫你别喝咖啡了，你作何感受？如果有人告诉你生酮饮食是最好的，你作何感受？你是不是想给他们上上课，告诉他们你“知道”什么是最好的，或者你对此有多丰富的经验？你想捍卫你附加在自己身份认同上的、觉得有必要维持生存的那些意识形态？哪怕你明知道这种一概而论的说法根本不可能适用于地球上每一个身处不同文化、拥有不同资源的人？</p><p>如果你是个高效的人，当你搬到一个新地方时，感觉如何？你的日常规律瞬间被打破了。你原本正通过努力、精力和习惯来维持“日常规律”这种形态的生存。你需要一两个星期来“适应”，对吧？</p><p>这正是我经常沦为奴隶的地方。沦为我日常规律的奴隶。</p><p><strong>宗教意识形态</strong></p><p>即使人们说他们不在乎是否能把你拉进他们的信仰体系，他们依然会在无意识中这么做。因为他们习惯于复制自己的身份认同。</p><p>生存包含繁衍（复制），而我们通过交流传递给他人的任何观念都会影响另一个人的身份认同。</p><p>你的“自我”是一个概念。它是一张由观念和信仰交织而成的网。这些观念和信仰会随时间改变。你吸收的任何一条信息，都会对你是谁产生影响。</p><p>这就是为什么精神上的手机奴隶往往以失败告终。他们每天所做的就是消费那些自贬的表情包，麻木自己的头脑，以避免面对他们处境的真相。</p><p>奴役是强大的，因为如果我们习惯于维持一种身份的生存（比如某个职位头衔），而当我们想要辞掉那份工作时，生存受到威胁的力量就会把我们死死绑在上面。</p><h2 id="社会是一个注意力的传销骗局" tabindex="-1">社会是一个注意力的传销骗局 <a class="header-anchor" href="#社会是一个注意力的传销骗局" aria-label="Permalink to &quot;社会是一个注意力的传销骗局&quot;">​</a></h2><p>如果没有被给予注意力，它就不存在。</p><p>如果它不存在，就必须投入注意力让它活下来。</p><p>这带来了两个感悟：</p><p><strong>1) 你正在助长无意识的毁灭。</strong></p><p>巨型企业是如何发展壮大的？</p><p>它们从小做起，随着时间的推移形成了一个权力等级制度。</p><p>顶层的人数更少、权力更大，底层的人数更多、权力更小。</p><p>等级制度的顶层（公司和高管）之所以能做他们所做的事，仅仅是因为有一大群人自下而上地把注意力集中在这些任务、愿景和价值观上。</p><p>底层由低技能的苦力活组成，比如麦当劳的收银员，然后向上延伸到营销和商业运营，直到你到达顶层。</p><p>从本质上讲，大量的人是不可能在这个等级制度中晋升的。</p><p>问题在于，处于底层的人没有意识到他们的工作所产生的影响。</p><p>就像麦当劳是如何用他们的食物毒害大众的（收银员有丰富的营养和健康知识吗？没有，否则他们就不会在那里工作，他们可能会在营养学领域）。</p><p>或者是军方程序员如何为无人机编写代码，执行命令去杀死国家另一边的人。</p><p>甚至是一个为诈骗课程创作者设计网页的网页设计师。</p><p><em>“宽恕他们吧，因为他们不知道自己在做什么。”</em></p><p><strong>2) 你可以把一个有意识的愿景变成现实。</strong></p><p>逃离的唯一出路就是建立你自己的事业。</p><p>但是，当你沦为那些榨干你时间和精力的事物的奴隶时，这就变得越来越困难。</p><p>你花了 20 年、30 年，甚至可能是 40 年才把自己嵌进这个现实中。要摆脱它应该花不了那么长时间，但请保持一点耐心。</p><p>出路就是<a href="/letters/the-value-creator-a-new-internet-career-path-for-intelligent-people">成为一名价值创作者。</a></p><p>真正的价值是具有创造性的。</p><p>创造力允许改变和涌现的发生。</p><p>它允许原本试图维持生存的形态、自我或身份认同进化成全新的东西。</p><p>如果你能提供的唯一价值是体力，你就会被困在体力劳动的工作中（而顶层的人则用他们的大脑赚钱）。</p><p>正如我们经常谈到的，你必须：</p><ul><li>打破未知的边界</li><li>在前进的道路上学习和发现新的潜能</li><li>掌握打造有目标感的产品所需的技能</li><li>解决你自己的问题，从而创造出具有真正价值的解决方案</li><li>开创一家企业，作为实现你对未来愿景的载体</li></ul><p>你必须建立自己的有意识的等级制度，将无意识的破坏降到最低。</p><h2 id="薪酬奴隶" tabindex="-1">薪酬奴隶 <a class="header-anchor" href="#薪酬奴隶" aria-label="Permalink to &quot;薪酬奴隶&quot;">​</a></h2><p>我厌倦了争论的双方。</p><p>“朝九晚五的打工人都是奴隶！”</p><p>“没关系强尼，如果你做着朝九晚五的工作，你并不是奴隶。”</p><p>双方都错了。双方也都对。</p><p>双方都试图获得最大的互动量，提升自己品牌的地位。他们没有拉远视角，去思考人们到底是不是真的奴隶。一个发表出来的却没有深度和理解的观点，对人类是一种伤害。</p><p>事实的真相是，95%以上的朝九晚五打工人都是奴隶。</p><p>你的感受在这里并不重要。如果你真的觉得自己被屏幕上的文字威胁到了，那也许我说的确实有几分道理。向内看，看看你到底在逃避什么。</p><p>大多数打工人就是字面定义上的奴隶。</p><p>如果你为了生存无法停止去上班，又没有技能可以立刻开启其他选项，而且你还是某家公司的“财产”或<em>员工</em>……那就是奴隶。</p><p>当然，这并不意味着你不能拥有幸福。</p><p>每个人都在以这样或那样的方式做着奴隶，我们的一生中也都会有一波又一波的幸福。</p><p>如果幸福是指当我们的注意力从这个世界巨大的不幸中转移时所获得的感觉，那么被奴役可能会让一些人比不被奴役的人更快乐。</p><p>你可以在对生活中的问题毫无意识的情况下感到快乐（在你人生的某些时刻）。</p><p>但一旦你意识到了它们，真正地意识到了它们，你就会感受到驱使你进化的拉力。</p><p>我来这里不是为了妖魔化朝九晚五的工作。</p><p>我把它们视为<em>必要的</em>垫脚石。</p><p>我同样也将那些入门级的商业模式（如代理服务、自由职业、教练咨询甚至数字产品）视为你毕生事业的垫脚石。它们很容易就会将你奴役。</p><p>然而，个人品牌并不是一种商业模式。它是随着你的不断进化，为你希望分发的任何产品或服务建立受众群体的方式。</p><p>个人品牌就是你在数字社会中的角色。</p><p>很多人<em>注定</em>会被困在等级制度的某个层级里。也许那就是他们的宿命。那也没关系。</p><p>就像电子游戏一样的虚拟现实，其构建的社会是由 NPC（非玩家角色）来维系的。在互联网上，这些角色就是那些无意识的网络喷子、消费者和评论区的杠精（reply guys）。</p><p>事实是，大多数人依然不会意识到他们对这个世界产生的影响。</p><p>我无法改变他们，你也无法改变他们，但我们可以改变自己在生活中所做的事。</p><h2 id="创业是现代的生存方式" tabindex="-1">创业是现代的生存方式 <a class="header-anchor" href="#创业是现代的生存方式" aria-label="Permalink to &quot;创业是现代的生存方式&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>对于长期主义者来说，创业是唯一符合逻辑的选择。</p><p>如果你在朝九晚五的工作中待得太久，你就会变成格子间里的猴子。</p><p>你的心智天生就是为了狩猎而设计的。</p><p>狩猎就是去做出有助于你生存的新奇发现。</p><p>想象一下我们的祖先每天经过一丛光秃秃的灌木。这对他们的未来毫无用处。</p><p>但是有一天，它长出了新的浆果。</p><p>有人经过它，注意到了它，这种新奇感引发了兴奋。他们要么把浆果采走，要么记住它们留待日后使用，这样他们就能存活得更久。</p><p>当你被困在朝九晚五（或者像代理业务或自由职业这样新型的朝九晚五）中时，你就活在永恒的已知之中。你无法在已知中做出新的发现。</p><p>你会感到无聊、抑郁，觉得生活毫无意义，因为你获取多巴胺的唯一来源都是些肤浅的东西。</p><p>你从不冒险，从不迈向未知，从不探索那些能提升大脑多巴胺水平的新知识、新工具和新潜能。</p><p>你必须进化。</p><p>创业是一条充满不确定性的道路。</p><p>就像在丛林中披荆斩棘。</p><p>你需要去学习学校里不教的技能。</p><p>你需要坦然接受失败、拒绝和缓慢的进展。</p><p>你需要从错误中学习，明天再次整装待发，不断向前推进，直到你挖到金矿。</p><p>作为一名创业者，你通过收集知识、打造有价值的产品、并将它展现在能从中受益的人面前，来“狩猎”以求生存。</p><p>正如我所讨论过的，我实现这一目标的路径是：</p><ul><li>以个人品牌为基础起步</li><li>在现实世界中解决你自己的问题（健康、财富、人际关系）</li><li>通过写作传播你的发现、观点和信念</li><li>从自由职业或教练服务开始，并取得成果</li><li>（一旦你的受众增长）销售需要较少时间投入的实体或数字产品</li><li>通过坚持和迭代，在2-4年内赚取丰厚的收入</li><li>拓展你对未来的愿景，并为实现它去打造任何你想打造的东西（软件、宇宙飞船，任何你想要的）</li></ul><p>这就是我在 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a> 中提供的整个流程，包含模板和教学。</p><h2 id="技能与机会" tabindex="-1">技能与机会 <a class="header-anchor" href="#技能与机会" aria-label="Permalink to &quot;技能与机会&quot;">​</a></h2><p>在生活中，我是许多事物的奴隶，但我愿意相信，我已经逃离了工资奴役。</p><p>如果我的企业从地球上彻底消失，我仍然可以：</p><ul><li>创造出别人需要的产品或服务</li><li>打电话、发邮件、做广告，并在互联网上传播内容，为该产品或服务引流</li><li>在第一个月赚到5千到1万美元，并利用我收集到的数据进行改进</li></ul><p>为什么我能做到，而大多数人却做不到？</p><p>因为在过去的10年里，我学习了平面设计、视频剪辑、文案写作、心理学、网页开发、市场营销、销售、邮件营销、演讲、受众建设、广告推广、产品设计、课程制作、创意生成、生活方式设计、健身健美、营养学，以及更多让大众感到挣扎的技能。</p><p>即使我身无分文，我也能创造一项服务，教人们如何制作一个能卖出货的着陆页。</p><p>我会为一个包含4次通话的“训练营”收取1000到2500美元，具体取决于我想如何构建这个报价方案。</p><p>我设定的目标客户会是拥有完整网站的新企业（因为那离销售产品或服务的最佳方式还差得远）。或者，我会把目标对准那些想在就业之外学习一项赚钱技能的学生。或者，我会针对那些希望在平台收入之外迈出品牌变现第一步的创作者。</p><p>我会每天早上花3个小时给人们发私信，并在网上撰写营销内容。</p><p>人们会读到这里，然后试图复制它。</p><p>然而，他们会失败，因为他们不明白<em>经验</em>的力量有多强大。其中有太多微妙的细节和思维过程，初学者必须花精力去重新编程。</p><p>当你去上学时，你被局限在少数几项特定的技能上，以此将你训练成能胜任某个雇佣岗位的人。</p><p>我在学校之外学到的每一项技能，都能让我发现多个机会，让我在工作之外赚取收入。</p><p>这种效应会产生复利。</p><p>凭借我培养出的技能，我可以写出50种不同的产品，而且我知道它们都会在我努力的前6个月内实现盈利。</p><p>在这里，技能是由经验决定的。</p><p>你不能只是了解一下它们，就指望能在市场上看到我所能看到的东西。</p><p>你还没有失败到足以理解所有这些商业事务背后的微妙之处。</p><p>如果你想逃离，以下是你如何发现机会并培养技能以实现它的方法：</p><p><strong>1) 沉浸在新信息中为你的大脑编程</strong></p><p>大多数人正淹没在与他们目标无关的信息中。</p><p>他们没有愿景、目标或问题来作为解读信息的透镜。</p><p>很有可能你已经读过能改变一生的信息，但它并没有在你的意识中留下印象。</p><p>当你把“逃离工资奴役”的目标放在首位时，你可以：</p><ul><li>每天至少安排20分钟，专门用于摄取有助于实现该目标的信息。</li><li>买书、使用你的Audible积分、收藏播客、关注新的社交账号，并在YouTube上把新视频加入“稍后观看”</li><li>走出家门，在手机上打开一个笔记应用，当你沉浸在这些信息中时，写下你的发现。</li></ul><p>在追寻更好生活的过程中，你会感觉到大脑里多巴胺的分泌。</p><p><strong>2) 研究你渴望打造的目标驱动型企业</strong></p><p>既然你已经有了内容消费的习惯，你需要一个更实际的目标来应用你所学的知识。</p><p>你要建立什么样的企业来逃离工资奴役？</p><ul><li>在脑海中留意你日常使用的应用和参与的活动。</li><li>看看你关注了谁，以及他们建立的企业。</li><li>买一本关于你感兴趣的特定商业模式的书或课程。</li></ul><p>你必须找到一种让你有冲动去打造的商业模式。</p><p>一种能让你为之着迷的模式。</p><p>是哪一种并不重要。</p><p><em>模仿</em>成就了我第一批成功的企业。</p><p>它帮我找出了盲区。</p><p>那些盲区通常是阻碍我获得成功的关键因素。</p><p>养成一种习惯去研究你想成为的人，下载并购买他们提供的所有东西，并对他们在网上拥有的一切（社交媒体资料、网站、着陆页、邮件序列、产品、服务、引流诱饵、书籍，所有一切）制作一个思维导图。</p><p>逆向工程找出让他们取得成功的原因。</p><p>如果在那之后你还不知道该怎么做，那我就不知道该说什么了。</p><p><strong>3) 成为你自己的多巴胺贩子</strong></p><p>前几天我和我的朋友进行了一次讨论。</p><p>我来转述一下他说的话。</p><p><em>你知道最不可思议的是什么吗……我记得曾问过你，为什么你朋友里没有一个人采取行动或者跟随你的脚步。现在我明白了。</em></p><p><em>人们都是多巴胺瘾君子，甚至连商人也不例外。</em></p><p><em>那些不采取行动的人，不知道如何用商业来替代他们从现有习惯中获取的多巴胺</em>_。_</p><p><em>所以，他们要么干脆不开始，要么在一个星期后就放弃了，因为他们得不到那种刺激。</em></p><p>这让我回想起来，并意识到是什么让我在这一路上坚持了下来。</p><p>我一直在追逐那美好的多巴胺，只不过是在正确的方向上。</p><p>所以，我的建议是：</p><ul><li>对你在生活中想要什么（金钱、成功、平静、成就感）保持一个宽泛的概念。</li><li>开始打造些东西，任何东西，只要能让它成为现实——当然，我会推荐一人企业，因为它是长期的。</li><li>学习你最想学的东西来帮助建立它（技能、课程、网站、Logo，随便什么），这样你就能获得多巴胺刺激。</li><li>如果你觉得无聊了，不要害怕改变你正在做的事情。</li></ul><p>我将我独特的成功归因于“闪亮物体综合症”。</p><p>我尝试过并 <a href="/letters/i-failed-at-7-online-business-models-and-turned-it-into-a-full-time-creative-income">在7种不同的商业模式上失败了。</a></p><p>大多数人没有看到的是，如果没有那些失败，我就不会有今天。</p><p>我在每次失败中学到的技能复利般地转化为了更好的机会。</p><p>如果没有文案写作技巧，我的推文就不会是现在这样。</p><p>如果没有网页设计技能，我的网页就不会是现在这样。</p><p>如果没有Photoshop艺术创作，我的头像和品牌形象就不会是现在这样。</p><p>这样的例子数不胜数。</p><p>用能让你获得自由的习惯，去替换那些让你受到奴役的习惯。</p><p>这不会一蹴而就。</p><p>要坦然接受这一点。</p><p>如果你能在这个方向上坚持走下去，你就赢了。</p><hr><p><a href="/en/letters/entrepreneurship-is-modern-survival-how-to-escape-wage-slavery">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',183))])}const k=t(m,[["render",h]]);export{w as __pageData,k as default};
